INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z27-q28','nism-5a-z27','A goal costs ₹62,000 today. With inflation of 7% p.a., its cost after 9 years will be approximately:','["₹1,06,528","₹1,13,984","₹1,21,963","₹1,01,060"]',1,'FV = 62000 × (1 + 7%)^9.',28) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
