INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z32-q77','nism-5a-z32','Under the AMFI Code for Distributors, an MFD may NOT:','["Explain risks","Disclose commissions","Offer rebates of commission, gifts or vouchers","Quote EUIN"]',2,'No rebating is permitted.',77) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z32-q78','nism-5a-z32','Index funds and ETFs offer:','["Market return with no selection risk and lower cost","Higher cost than active funds","Protection when the index falls","Guaranteed returns"]',0,'Their NAV still falls when the index falls.',78) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z32-q79','nism-5a-z32','The standard additional benchmark for equity schemes is:','["Gold price","Sensex or Nifty","1-year T-bill","10-year GoI security"]',1,'Debt ≤1 year and Arbitrage: 1-year T-bill; others: 10-year GoI.',79) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
