INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5a-z32-q81','nism-5a-z32','A portfolio of ₹24,00,000 is 50:50 equity:debt. Equity rises 10% and debt is unchanged. To rebalance to the original ratio, the amount of equity to be sold is:','["₹90,000","₹60,000","₹1,20,000","₹2,40,000"]',1,'New equity = 1320000; target = 1260000; sell the excess.',81) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
